/**
 * 의료진용 한 장 요약: the latest assessment, the trend since onset, muscle and synkinesis maps and exercise
 * adherence on one A4 page, printed or saved as PDF with the browser (nothing leaves the device).
 */
import {
  ALGORITHM_ID,
  ALGORITHM_VERSION,
  HB_ROMAN,
  MOVEMENT_TASKS,
  MUSCLE_ORDER,
  SCORING,
  SCORING_VERSION,
  isReferenceMuscle,
  isScoredTask,
  type CouplingRegion,
} from '../../core';
import { FEATURES } from '../../config';
import { daysBetween, localDate } from '../../data/db';
import { latestRating } from '../../data/export';
import { APP_INFO } from '../../data/records';
import { useApp } from '../../data/store';
import type { RehabLog } from '../../data/types';
import { changeSummary } from '../../rehab/findings';
import { exerciseById } from '../../rehab/exercises';
import { FEEL_LABEL, type Feel } from '../../rehab/dose';
import { AppBar } from '../components/common';
import { AnatomyFace, FaceMap, type RegionValues } from '../components/FaceMap';
import { LineChart } from '../components/LineChart';
import { MUSCLE, muscleMapValues, muscleView } from '../components/MuscleCard';
import { Icon } from '../icons';
import { CHANGE_FELT_LABEL, ETIOLOGY_LABEL, SIDE_LABEL, TASK_SHORT, dayLabel, fmtDate, fmtDateTime, maxMm, ratioView } from '../labels';
import { describe, synkValues } from '../synk';

const fx = (x: number, d = 1): string => (Math.abs(x) < 0.5 * 10 ** -d ? 0 : x).toFixed(d);

/** Exercise days and minutes in the `days` days up to today. */
export function adherence(
  logs: readonly RehabLog[],
  days: number,
  today: Date = new Date(),
): { days: number; minutes: number; top: string[]; feels: Partial<Record<Feel, number>> } {
  const from = new Date(today);
  from.setDate(from.getDate() - (days - 1));
  const lo = localDate(from);
  const hi = localDate(today);
  const inRange = logs.filter((l) => l.date >= lo && l.date <= hi);
  const count = new Map<string, number>();
  for (const l of inRange) count.set(l.exerciseId, (count.get(l.exerciseId) ?? 0) + 1);
  const feels: Partial<Record<Feel, number>> = {};
  for (const l of inRange) if (l.feel) feels[l.feel] = (feels[l.feel] ?? 0) + 1;
  return {
    feels,
    days: new Set(inRange.map((l) => l.date)).size,
    minutes: Math.round(inRange.reduce((s, l) => s + l.durationSec, 0) / 60),
    top: [...count.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([id, n]) => `${exerciseById(id)?.title ?? id} ${n}회`),
  };
}

function printLight(): void {
  // Print in the light theme whatever the screen uses, then restore.
  const root = document.documentElement;
  const had = root.dataset.theme;
  root.dataset.theme = 'light';
  const restore = () => {
    if (had === undefined) delete root.dataset.theme;
    else root.dataset.theme = had;
    window.removeEventListener('afterprint', restore);
  };
  window.addEventListener('afterprint', restore);
  window.print();
}

export function Report() {
  const { profile, sessions, synk, rehab, ratings, integrity } = useApp();
  if (!profile) return null;
  const scored = sessions.filter((s) => s.analysis.scores);
  const latest = scored[scored.length - 1];
  const prev = scored[scored.length - 2];
  const today = new Date();
  const sinceOnset = daysBetween(profile.onsetDate, today);
  const a = latest?.analysis;
  const sc = latest?.analysis.scores ?? null;
  const aff = a?.affectedSide ?? profile.affectedSide;
  const healthy = aff === 'left' ? 'right' : 'left';
  const rating = latest ? latestRating(ratings, latest.id) : undefined;
  const y = latest ? (synk.find((r) => r.sessionId === latest.id) ?? synk[synk.length - 1]) : synk[synk.length - 1];
  const sv = y ? synkValues(y.result, 'all') : null;
  const synkMap: RegionValues = sv ? Object.fromEntries(Object.entries(sv.v).map(([g, x]) => [g, Math.min(1, x / 3)])) : {};
  const synkLines = sv
    ? (Object.entries(sv.worst) as [CouplingRegion, NonNullable<(typeof sv.worst)[CouplingRegion]>][])
        .sort((p, q) => (sv.v[q[0]] ?? 0) - (sv.v[p[0]] ?? 0))
        .map(([g, e]) => `${describe(y!.result, e, g)}${y!.result.cells[e]![g].mild ? ' (미세)' : ''}`)
    : [];
  const m = latest?.muscles;
  const map = m ? muscleMapValues(m) : null;
  const weakMuscles = m
    ? MUSCLE_ORDER.filter((id) => m.items[id] && !isReferenceMuscle(id))
        .map((id) => ({ id, v: muscleView(m, id), r: m.items[id]!.ratio }))
        .filter((x) => x.v.kind === 'pct')
        .sort((p, q) => (p.r ?? 1) - (q.r ?? 1))
    : [];
  const a4 = adherence(rehab, 28, today);
  const a1 = adherence(rehab, 7, today);
  const verified = [...sessions, ...synk].filter((r) => integrity[r.id]).length;
  const trend = [
    {
      id: 'ffi',
      label: '움직임 %',
      color: 'var(--series-1)',
      points: scored.map((s) => ({ x: s.daysSinceOnset, y: s.analysis.scores!.functionIndex })),
    },
    ...(FEATURES.estimatedScales
      ? [
          {
            id: 'sb',
            label: 'Sunnybrook(추정)',
            color: 'var(--series-2)',
            points: scored.map((s) => ({ x: s.daysSinceOnset, y: s.analysis.scores!.composite })),
          },
        ]
      : []),
  ];

  return (
    <>
      <AppBar
        title="의료진용 요약"
        onBack
        right={
          <button class="btn sm primary" onClick={printLight}>
            <Icon name="download" /> 인쇄·PDF
          </button>
        }
      />
      <main class="main report">
        <p class="xsmall muted no-print" style={{ margin: 0 }}>
          진료 때 보여 드리거나 ‘인쇄·PDF’로 저장해 전달하세요. 이 폰 밖으로 자동으로 보내지 않습니다.
        </p>
        <header class="rp-head">
          <div>
            <h1>안면마비 경과 요약</h1>
            <div class="small">
              {profile.nickname || '이름 없음'} · 마비 쪽 {SIDE_LABEL[profile.affectedSide]} · 발병 {profile.onsetDate} (
              {dayLabel(sinceOnset)}) · {ETIOLOGY_LABEL[profile.etiology]}
              {profile.birthYear ? ` · ${profile.birthYear}년생` : ''}
            </div>
          </div>
          <div class="xsmall muted" style={{ textAlign: 'right' }}>
            {fmtDate(today.toISOString())} 작성
            <br />
            환자 자가 측정 · 참고용
          </div>
        </header>

        {!latest || !a || !sc ? (
          <div class="card">점수가 계산된 평가가 아직 없습니다. 평가를 한 번 마치면 요약이 만들어집니다.</div>
        ) : (
          <>
            <section class="rp-grid">
              <div class="card rp-box">
                <h3>
                  최근 평가 · {fmtDateTime(latest.createdAt)} ({dayLabel(latest.daysSinceOnset)})
                </h3>
                <div class="row" style={{ alignItems: 'baseline', gap: '6px' }}>
                  <span class="hero-num">{sc.functionIndex}</span>
                  <span class="hero-unit">%</span>
                  <span class="small ink2">마비 쪽 움직임(건강한 쪽 = 100%)</span>
                </div>
                <table class="data rp-table">
                  <tbody>
                    <tr>
                      <td>이마 {sc.regional.forehead}%</td>
                      <td>눈 {sc.regional.eye}%</td>
                      <td>코·볼 {sc.regional.midface}%</td>
                      <td>입 {sc.regional.mouth}%</td>
                    </tr>
                  </tbody>
                </table>
                {FEATURES.estimatedScales && (
                  <div class="small">
                    Sunnybrook(추정) <b>{sc.composite}</b> = 수의 {sc.voluntaryScore} − 안정 {sc.restScore} − 동반 {sc.synkinesisScore} ·
                    HB(추정) <b>{HB_ROMAN[sc.houseBrackmann.grade]}</b> · 눈 {sc.eyeClosureComplete ? '완전히 감김' : '덜 감김'}
                  </div>
                )}
                {prev && (
                  <div class="small" style={{ marginTop: '4px' }}>
                    {changeSummary(a, prev.analysis, latest.daysSinceOnset - prev.daysSinceOnset)}
                  </div>
                )}
                {latest.patientReport && (
                  <div class="small">환자가 느낀 변화(직전 대비): {CHANGE_FELT_LABEL[latest.patientReport.changeSinceLast]}</div>
                )}
                {rating && (
                  <div class="small" style={{ marginTop: '4px' }}>
                    임상가 평가({rating.raterId}): HB {rating.houseBrackmann ? HB_ROMAN[rating.houseBrackmann] : '–'} · Sunnybrook{' '}
                    {rating.sunnybrookComposite ?? '–'}
                  </div>
                )}
              </div>
              <div class="card rp-box">
                <h3>경과 ({scored.length}회 평가)</h3>
                {scored.length >= 2 ? (
                  <LineChart
                    ariaLabel="움직임 추이"
                    series={trend}
                    yMax={100}
                    yTicks={[0, 25, 50, 75, 100]}
                    xLabel={(x) => `${x}일`}
                    xTitle="발병 후 일수"
                    height={150}
                  />
                ) : (
                  <p class="small muted">평가가 2회 이상이면 추이가 그려집니다.</p>
                )}
                <div class="xsmall ink2">
                  {trend.map((s) => (
                    <span style={{ marginRight: '10px' }}>
                      <span style={{ color: s.color }}>■</span> {s.label}
                    </span>
                  ))}
                  {scored.length >= 2 && `첫 평가 ${scored[0]!.analysis.scores!.functionIndex}% → 최근 ${sc.functionIndex}%`}
                </div>
              </div>
            </section>

            <div class="card rp-box">
              <h3>동작별 측정 (최근 평가)</h3>
              <table class="data rp-table">
                <thead>
                  <tr>
                    <th>동작</th>
                    <th>건강한 쪽</th>
                    <th>마비 쪽</th>
                    <th>대칭</th>
                    <th>수의(1–5)</th>
                    <th>동반(0–3)</th>
                  </tr>
                </thead>
                <tbody>
                  {MOVEMENT_TASKS.map((t) => {
                    const r = a.tasks[t];
                    if (!r) return null;
                    const val = (side: 'left' | 'right') =>
                      r.excursionMm
                        ? `${fx(r.excursionMm[side])} mm`
                        : t === 'eyeClose'
                          ? `${Math.round(r.excursion[side] * 100)}%`
                          : fx(r.excursion[side], 3);
                    const rv = ratioView(r.ratio, t === 'eyeClose' ? null : maxMm(r.excursionMm));
                    return (
                      <tr>
                        <td>
                          {TASK_SHORT[t]}
                          {SCORING.lowConfidenceTasks.includes(t) ? ' (참고)' : ''}
                        </td>
                        <td>{val(healthy)}</td>
                        <td>{val(aff)}</td>
                        <td>{!isScoredTask(t) ? '제외' : r.reliable ? rv.text : '–'}</td>
                        <td>{r.reliable && isScoredTask(t) ? r.grade : '–'}</td>
                        <td>{r.reliable ? r.synkinesisGrade : '–'}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <section class="rp-grid">
              <div class="card rp-box">
                <h3>근육별 (진할수록 약함)</h3>
                {m && map ? (
                  <div class="rp-map">
                    <div class="rp-face">
                      <AnatomyFace affectedSide={m.affectedSide} values={map.values} inferred={map.inferred} tone="weak" />
                    </div>
                    <ul class="xsmall">
                      {weakMuscles.slice(0, 5).map((x) => (
                        <li>
                          {MUSCLE[x.id].name}({MUSCLE[x.id].action}) {x.v.text}
                        </li>
                      ))}
                      {MUSCLE_ORDER.filter(
                        (id) => m.items[id] && muscleView(m, id).kind !== 'pct' && muscleView(m, id).kind !== 'full',
                      ).map((id) => (
                        <li class="muted">
                          {MUSCLE[id].name}: {muscleView(m, id).text}
                        </li>
                      ))}
                    </ul>
                  </div>
                ) : (
                  <p class="small muted">빠른 평가라 근육별 값이 없습니다(정밀 평가에서 측정).</p>
                )}
              </div>
              <div class="card rp-box">
                <h3>연합운동 {y ? `· ${fmtDate(y.createdAt)}` : ''}</h3>
                {y ? (
                  <div class="rp-map">
                    <div class="rp-face">
                      <FaceMap affectedSide={y.profileSnapshot.affectedSide} values={synkMap} tone="synk" />
                    </div>
                    <ul class="xsmall">
                      {synkLines.length ? synkLines.slice(0, 5).map((l) => <li>{l}</li>) : <li>함께 움직임이 보이지 않았습니다.</li>}
                    </ul>
                  </div>
                ) : (
                  <p class="small muted">연합운동 기록이 없습니다(정밀 평가 또는 ‘연합운동 찾기’에서 측정).</p>
                )}
              </div>
            </section>
          </>
        )}

        <div class="card rp-box">
          <h3>재활 운동 실천</h3>
          <div class="small">
            최근 4주 {a4.days}/28일 · {a4.minutes}분 · 최근 1주 {a1.days}/7일 · {a1.minutes}분
            {a4.top.length > 0 && <span class="ink2"> · 많이 한 운동: {a4.top.join(', ')}</span>}
            {Object.keys(a4.feels).length > 0 && (
              <span class="ink2">
                {' '}
                · 운동 후 느낌:{' '}
                {(Object.keys(FEEL_LABEL) as Feel[])
                  .filter((f) => a4.feels[f])
                  .map((f) => `${FEEL_LABEL[f]} ${a4.feels[f]}`)
                  .join(', ')}
              </span>
            )}
          </div>
        </div>

        <footer class="xsmall muted rp-foot">
          환자가 스마트폰으로 직접 측정한 참고값입니다(연구용 시제품, 임상 검증 전). 진단·치료 결정은 진료 소견을 따릅니다. 100~115%는
          100%로, 양쪽 3 mm 미만은 ‘움직임 작음’으로, ±5%p 안 변화는 ‘변화 없음’으로 표시(잠정 기준). 앱 v{APP_INFO.version} ·{' '}
          {ALGORITHM_ID} v{ALGORITHM_VERSION} · {SCORING_VERSION} · 기록 봉인 확인 {verified}/{sessions.length + synk.length}건
        </footer>
      </main>
    </>
  );
}
